-- scripts/seed.mts tarafından üretildi; elle düzenleme. Tedarikçi: supabase
begin;
delete from public.promotions where supplier_id = (select id from public.suppliers where email = 'supabase');
delete from public.orders where supplier_id = (select id from public.suppliers where email = 'supabase');
delete from public.products where supplier_id = (select id from public.suppliers where email = 'supabase');
create temp table _pid (seed_id text, id uuid) on commit drop;
with ins as (insert into public.products (supplier_id,name,brand,category,price,stock,unit,active,featured) values ((select id from public.suppliers where email = 'supabase'),'Mat Şekillendirici Wax 100 ml','Atlas Pro','Şekillendirici',145,320,'adet',true,true) returning id) insert into _pid select 'p1', id from ins;
